insert into public.questions (id, ask_stage, sort_order, answer_kind, prompt_en, prompt_hi, prompt_mr, help_en, help_hi, help_mr, depends_on) values
  ('q_activity', 1, 1, 'activity_search', 'What work will you do?', 'आप कौन सा काम करेंगे?', 'तुम्ही कोणता व्यवसाय करणार?', 'Type in your own words, like achaar, murgi palan or silai. You can choose two.', 'अपने शब्दों में लिखें, जैसे अचार, मुर्गी पालन या सिलाई। आप दो काम चुन सकते हैं।', 'तुमच्या शब्दांत लिहा, जसे लोणचे, कुक्कुटपालन किंवा शिवणकाम. तुम्ही दोन व्यवसाय निवडू शकता.', null),
  ('q_state', 2, 1, 'single', 'Which state will the work be in?', 'आपका काम किस राज्य में होगा?', 'तुमचा व्यवसाय कोणत्या राज्यात असेल?', null, null, null, null),
  ('q_district', 2, 2, 'text', 'Which district?', 'कौन सा जिला?', 'कोणता जिल्हा?', 'This helps us find your local offices.', 'इससे हम आपके स्थानीय कार्यालय ढूंढ पाते हैं।', 'यामुळे तुमची स्थानिक कार्यालये शोधता येतात.', null),
  ('q_area', 2, 3, 'single', 'Will it be in a village or a town?', 'काम गांव में होगा या शहर में?', 'व्यवसाय गावात असेल की शहरात?', 'Many schemes give more subsidy in rural areas.', 'कई योजनाएं ग्रामीण क्षेत्र में ज्यादा सब्सिडी देती हैं।', 'अनेक योजना ग्रामीण भागात जास्त अनुदान देतात.', null),
  ('q_stage', 3, 1, 'single', 'How far along is your work?', 'आपका काम अभी किस स्तर पर है?', 'तुमचा व्यवसाय सध्या कोणत्या टप्प्यावर आहे?', null, null, null, null),
  ('q_operating_since', 3, 2, 'date', 'Since when has it been running?', 'यह काम कब से चल रहा है?', 'हा व्यवसाय केव्हापासून सुरू आहे?', null, null, null, '{"all":[{"field":"stage","operator":"equals","value":"running"}]}'::jsonb),
  ('q_project_cost', 4, 1, 'band', 'How much will the whole project cost?', 'पूरे काम में कुल कितना खर्च आएगा?', 'संपूर्ण प्रकल्पाला एकूण किती खर्च येईल?', 'Machines, shed and first stock together. A rough figure is fine.', 'मशीन, शेड और शुरुआती सामान मिलाकर। अंदाज से बताना ठीक है।', 'यंत्रे, शेड आणि सुरुवातीचा माल मिळून. अंदाजे सांगितले तरी चालेल.', null),
  ('q_turnover', 4, 2, 'band', 'How much do you expect to sell in a year?', 'आप साल भर में कितनी बिक्री की उम्मीद करते हैं?', 'वर्षभरात किती विक्री होईल असे वाटते?', 'A rough guess is fine. This decides your FSSAI type and GST.', 'अंदाज से बताना ठीक है। इससे FSSAI का प्रकार और GST तय होता है।', 'अंदाजे सांगितले तरी चालेल. यावरून FSSAI चा प्रकार आणि GST ठरतो.', null),
  ('q_workers', 4, 3, 'number', 'How many people will work, including you?', 'आपको मिलाकर कितने लोग काम करेंगे?', 'तुमच्यासह किती लोक काम करतील?', null, null, null, null),
  ('q_own_money', 5, 1, 'band', 'How much money can you put in yourself?', 'आप अपनी तरफ से कितना पैसा लगा सकते हैं?', 'तुम्ही स्वतःचे किती पैसे घालू शकता?', 'Most schemes need 5–10% from you.', 'ज्यादातर योजनाओं में 5–10% अपना पैसा लगता है।', 'बहुतेक योजनांमध्ये 5–10% स्वतःचे पैसे लागतात.', null),
  ('q_needs_loan', 5, 2, 'yes_no', 'Will you need a loan?', 'क्या आपको लोन चाहिए?', 'तुम्हाला कर्ज हवे आहे का?', null, null, null, null),
  ('q_premises', 6, 1, 'single', 'Where will the work happen?', 'काम कहां होगा?', 'व्यवसाय कुठे चालेल?', null, null, null, null),
  ('q_premises_owner', 6, 2, 'single', 'Who owns that place?', 'वह जगह किसके नाम पर है?', 'ती जागा कोणाच्या नावावर आहे?', 'If it belongs to family, you may need a simple consent letter.', 'अगर जगह परिवार के नाम पर है, तो एक सहमति पत्र लग सकता है।', 'जागा कुटुंबाच्या नावावर असल्यास संमतीपत्र लागू शकते.', '{"all":[{"field":"premises_type","operator":"in","value":["home","rented_shop","own_shop","farm_land","pond_water"]}]}'::jsonb),
  ('q_land_pond', 6, 3, 'single', 'Is the land or pond yours?', 'क्या जमीन या तालाब आपका है?', 'जमीन किंवा तळे तुमचे आहे का?', 'Many farm and fish schemes need ownership or a registered lease.', 'कई खेती और मछली योजनाओं में मालिकाना हक या रजिस्टर्ड लीज चाहिए।', 'अनेक शेती आणि मत्स्य योजनांसाठी मालकी किंवा नोंदणीकृत भाडेकरार लागतो.', null),
  ('q_entity', 7, 1, 'single', 'What form is your business in?', 'आपका व्यवसाय किस रूप में है?', 'तुमचा व्यवसाय कोणत्या स्वरूपात आहे?', 'Not registered yet is fine. A home business rarely needs a company.', 'अभी पंजीकरण नहीं हुआ तो भी ठीक है। घरेलू काम के लिए कंपनी की जरूरत कम ही होती है।', 'अजून नोंदणी नसली तरी चालेल. घरगुती व्यवसायाला कंपनीची गरज क्वचितच असते.', null),
  ('q_have', 7, 2, 'multi', 'Tick what you already have', 'जो आपके पास पहले से है, उस पर टिक करें', 'तुमच्याकडे आधीच जे आहे त्यावर खूण करा', 'We never ask for the numbers, only whether you have them.', 'हम नंबर कभी नहीं पूछते, सिर्फ यह कि आपके पास है या नहीं।', 'आम्ही क्रमांक कधीच विचारत नाही, फक्त तुमच्याकडे आहे की नाही.', null),
  ('q_fssai', 7, 3, 'single', 'Do you have a food licence (FSSAI)?', 'क्या आपके पास खाद्य लाइसेंस (FSSAI) है?', 'तुमच्याकडे अन्न परवाना (FSSAI) आहे का?', null, null, null, null),
  ('q_age', 8, 1, 'number', 'How old are you?', 'आपकी उम्र कितनी है?', 'तुमचे वय किती आहे?', 'Many schemes have age limits, such as 18–40 or 18–50.', 'कई योजनाओं में उम्र की सीमा होती है, जैसे 18–40 या 18–50।', 'अनेक योजनांना वयोमर्यादा असते, जसे 18–40 किंवा 18–50.', null),
  ('q_education', 8, 2, 'single', 'How far have you studied?', 'आपने कहां तक पढ़ाई की है?', 'तुमचे शिक्षण किती झाले आहे?', 'Some schemes need Class 8 or Class 10 pass.', 'कुछ योजनाओं में 8वीं या 10वीं पास होना जरूरी है।', 'काही योजनांसाठी 8 वी किंवा 10 वी उत्तीर्ण असणे आवश्यक आहे.', null),
  ('q_gender', 8, 3, 'single', 'Are you a woman, a man or transgender?', 'आप महिला हैं, पुरुष हैं या ट्रांसजेंडर?', 'तुम्ही महिला, पुरुष की तृतीयपंथी आहात?', 'Women get higher subsidy under many schemes. You can choose not to say.', 'कई योजनाओं में महिलाओं को ज्यादा सब्सिडी मिलती है। आप न बताना भी चुन सकते हैं।', 'अनेक योजनांमध्ये महिलांना जास्त अनुदान मिळते. तुम्ही न सांगणेही निवडू शकता.', null),
  ('q_category', 8, 4, 'single', 'Which category do you belong to?', 'आप किस वर्ग से हैं?', 'तुम्ही कोणत्या प्रवर्गातील आहात?', 'Several schemes give SC, ST, OBC or EBC founders a higher subsidy or a reserved quota. You can choose not to say.', 'कई योजनाएं SC, ST, OBC या EBC को ज्यादा सब्सिडी या आरक्षित कोटा देती हैं। आप न बताना भी चुन सकते हैं।', 'अनेक योजना SC, ST, OBC किंवा EBC उद्योजकांना जास्त अनुदान किंवा राखीव कोटा देतात. तुम्ही न सांगणेही निवडू शकता.', null),
  ('q_minority', 8, 5, 'single', 'Do you belong to a notified minority community?', 'क्या आप अधिसूचित अल्पसंख्यक समुदाय से हैं?', 'तुम्ही अधिसूचित अल्पसंख्याक समुदायातील आहात का?', 'Some loans and state schemes are only for minority communities. You can choose not to say.', 'कुछ लोन और राज्य योजनाएं केवल अल्पसंख्यक समुदाय के लिए हैं। आप न बताना भी चुन सकते हैं।', 'काही कर्जे आणि राज्य योजना फक्त अल्पसंख्याक समुदायासाठी आहेत. तुम्ही न सांगणेही निवडू शकता.', null),
  ('q_ex_serviceman', 8, 6, 'yes_no', 'Have you served in the armed forces?', 'क्या आपने सेना में सेवा की है?', 'तुम्ही सशस्त्र दलात सेवा केली आहे का?', 'Ex-servicemen get special rates under some schemes.', 'कुछ योजनाओं में पूर्व सैनिकों को विशेष दर मिलती है।', 'काही योजनांमध्ये माजी सैनिकांना विशेष दर मिळतो.', null),
  ('q_disability', 8, 7, 'yes_no', 'Do you have a disability?', 'क्या आपको कोई दिव्यांगता है?', 'तुम्हाला दिव्यांगत्व आहे का?', 'Persons with disability get special rates under several schemes. You can choose not to say.', 'कई योजनाओं में दिव्यांगजन को विशेष दर मिलती है। आप न बताना भी चुन सकते हैं।', 'अनेक योजनांमध्ये दिव्यांग व्यक्तींना विशेष दर मिळतो. तुम्ही न सांगणेही निवडू शकता.', null),
  ('q_income', 8, 8, 'band', 'What is your family''s yearly income?', 'आपके परिवार की सालाना आय कितनी है?', 'तुमच्या कुटुंबाचे वार्षिक उत्पन्न किती आहे?', 'Some schemes are only for families below an income limit. You can choose not to say.', 'कुछ योजनाएं केवल तय आय सीमा से नीचे के परिवारों के लिए हैं। आप न बताना भी चुन सकते हैं।', 'काही योजना ठरावीक उत्पन्न मर्यादेखालील कुटुंबांसाठीच आहेत. तुम्ही न सांगणेही निवडू शकता.', null),
  ('q_prior_subsidy', 8, 9, 'yes_no', 'Have you taken a government subsidy before?', 'क्या आपने पहले कोई सरकारी सब्सिडी ली है?', 'तुम्ही यापूर्वी सरकारी अनुदान घेतले आहे का?', 'Several schemes do not allow a second subsidy.', 'कई योजनाओं में दूसरी बार सब्सिडी नहीं मिलती।', 'अनेक योजनांमध्ये दुसऱ्यांदा अनुदान मिळत नाही.', null),
  ('q_exact_cost', 9, 1, 'number', 'What is the exact project cost, in rupees?', 'काम की सही लागत कितने रुपये है?', 'प्रकल्पाचा नेमका खर्च किती रुपये आहे?', 'This decides whether your project is within the scheme''s limit.', 'इससे तय होता है कि आपका काम योजना की सीमा में है या नहीं।', 'यावरून तुमचा प्रकल्प योजनेच्या मर्यादेत आहे की नाही हे ठरते.', '{"all":[{"field":"project_cost_band","operator":"exists"}]}'::jsonb),
  ('q_matches_odop', 9, 2, 'yes_no', 'Is your product the ODOP product of your district?', 'क्या आपका उत्पाद आपके जिले का ODOP उत्पाद है?', 'तुमचे उत्पादन तुमच्या जिल्ह्याचे ODOP उत्पादन आहे का?', 'Each UP district has one chosen product, such as woodcraft in Saharanpur. You can check on odopup.in.', 'UP के हर जिले का एक चुना हुआ उत्पाद है, जैसे सहारनपुर में काष्ठ कला। आप odopup.in पर देख सकते हैं।', 'UP मधील प्रत्येक जिल्ह्याचे एक निवडलेले उत्पादन आहे, जसे सहारनपूरमध्ये लाकडी कलाकुसर. तुम्ही odopup.in वर पाहू शकता.', '{"all":[{"field":"state","operator":"equals","value":"uttar_pradesh"}]}'::jsonb),
  ('q_exports', 9, 3, 'yes_no', 'Will you sell outside India?', 'क्या आप भारत के बाहर बेचेंगे?', 'तुम्ही भारताबाहेर विक्री करणार का?', null, null, null, null),
  ('q_sells_packaged', 9, 4, 'yes_no', 'Will you sell in sealed packets?', 'क्या आप सीलबंद पैकेट में बेचेंगे?', 'तुम्ही बंद पाकिटात विक्री करणार का?', null, null, null, null),
  ('q_poultry_unit', 9, 5, 'single', 'What kind of poultry unit is it?', 'मुर्गी पालन की इकाई किस तरह की है?', 'कुक्कुटपालन युनिट कोणत्या प्रकारचे आहे?', null, null, null, '{"any":[{"field":"activity_codes","operator":"contains","value":"poultry_broiler"},{"field":"activity_codes","operator":"contains","value":"poultry_layer"},{"field":"activity_codes","operator":"contains","value":"poultry_backyard"},{"field":"activity_codes","operator":"contains","value":"poultry_breeding_hatchery"}]}'::jsonb),
  ('q_poultry_birds', 9, 6, 'number', 'How many birds will you keep?', 'आप कितनी मुर्गियां रखेंगे?', 'तुम्ही किती पक्षी ठेवणार?', 'For a breeding unit, count the parent birds.', 'प्रजनन इकाई के लिए पैरेंट पक्षी गिनें।', 'पैदास युनिटसाठी पालक पक्षी मोजा.', '{"any":[{"field":"activity_codes","operator":"contains","value":"poultry_broiler"},{"field":"activity_codes","operator":"contains","value":"poultry_layer"},{"field":"activity_codes","operator":"contains","value":"poultry_backyard"},{"field":"activity_codes","operator":"contains","value":"poultry_breeding_hatchery"}]}'::jsonb),
  ('q_goat_females', 9, 7, 'number', 'How many female goats or sheep will you keep for breeding?', 'प्रजनन के लिए कितनी मादा बकरी या भेड़ रखेंगे?', 'पैदाशीसाठी किती माद्या शेळ्या किंवा मेंढ्या ठेवणार?', null, null, null, '{"all":[{"field":"activity_codes","operator":"contains","value":"goat_sheep"}]}'::jsonb),
  ('q_goat_males', 9, 8, 'number', 'How many male goats or sheep will you keep for breeding?', 'प्रजनन के लिए कितने नर बकरे या भेड़ रखेंगे?', 'पैदाशीसाठी किती नर बोकड किंवा मेंढे ठेवणार?', null, null, null, '{"all":[{"field":"activity_codes","operator":"contains","value":"goat_sheep"}]}'::jsonb),
  ('q_sows', 9, 9, 'number', 'How many sows will you keep?', 'आप कितनी मादा सूअर रखेंगे?', 'तुम्ही किती माद्या डुकरे ठेवणार?', null, null, null, '{"all":[{"field":"activity_codes","operator":"contains","value":"piggery"}]}'::jsonb),
  ('q_boars', 9, 10, 'number', 'How many boars will you keep?', 'आप कितने नर सूअर रखेंगे?', 'तुम्ही किती नर डुकरे ठेवणार?', null, null, null, '{"all":[{"field":"activity_codes","operator":"contains","value":"piggery"}]}'::jsonb),
  ('q_artisan_trade', 9, 11, 'single', 'What is your trade?', 'आपका हुनर या पेशा क्या है?', 'तुमचा व्यवसाय किंवा कौशल्य कोणते आहे?', 'PM Vishwakarma covers 18 traditional trades.', 'PM विश्वकर्मा में 18 पारंपरिक पेशे शामिल हैं।', 'PM विश्वकर्मामध्ये 18 पारंपरिक व्यवसाय येतात.', null),
  ('q_rooms', 9, 12, 'number', 'How many rooms will guests use?', 'मेहमानों के लिए कितने कमरे होंगे?', 'पाहुण्यांसाठी किती खोल्या असतील?', null, null, null, '{"all":[{"field":"activity_codes","operator":"contains","value":"homestay"}]}'::jsonb),
  ('q_innovative', 9, 13, 'yes_no', 'Is your product new, or built on your own technology?', 'क्या आपका उत्पाद नया है या आपकी अपनी तकनीक पर बना है?', 'तुमचे उत्पादन नवीन आहे की तुमच्या स्वतःच्या तंत्रज्ञानावर आधारित आहे?', null, null, null, null),
  ('q_incorporation', 9, 14, 'date', 'When was your company registered?', 'आपकी कंपनी कब पंजीकृत हुई?', 'तुमची कंपनी केव्हा नोंदणीकृत झाली?', null, null, null, null)
